START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261016193650_AddEventCommerce') THEN
    CREATE TABLE "CatalogueItem" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SellerUserId" character varying(450) NOT NULL,
        "Title" character varying(200) NOT NULL,
        "Description" character varying(4000) NOT NULL,
        "PriceMinor" integer NOT NULL,
        "Currency" character varying(3) NOT NULL DEFAULT 'GBP',
        "StockQuantity" integer,
        "Category" integer NOT NULL,
        "ImageUrl" character varying(2048),
        "IsActive" boolean NOT NULL,
        "Version" bigint NOT NULL DEFAULT 1,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_CatalogueItem" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_CatalogueItem_AspNetUsers_SellerUserId" FOREIGN KEY ("SellerUserId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261016193650_AddEventCommerce') THEN
    CREATE TABLE "EventCommerceSettings" (
        "CompetitionId" integer NOT NULL,
        "IsDemo" boolean NOT NULL,
        "UpdatedByUserId" character varying(450),
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_EventCommerceSettings" PRIMARY KEY ("CompetitionId"),
        CONSTRAINT "FK_EventCommerceSettings_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261016193650_AddEventCommerce') THEN
    CREATE TABLE "EventOrder" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "BuyerUserId" character varying(450) NOT NULL,
        "IdempotencyKey" character varying(100) NOT NULL,
        "RequestHash" character varying(64) NOT NULL,
        "Status" integer NOT NULL,
        "TotalMinor" integer NOT NULL,
        "Currency" character varying(3) NOT NULL DEFAULT 'GBP',
        "IsTestOrder" boolean NOT NULL,
        "HasStockReservation" boolean NOT NULL,
        "PaidAt" timestamp with time zone,
        "CancelledAt" timestamp with time zone,
        "RefundedAt" timestamp with time zone,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_EventOrder" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_EventOrder_AspNetUsers_BuyerUserId" FOREIGN KEY ("BuyerUserId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_EventOrder_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
