        "LineTotalMinor" integer NOT NULL,
        CONSTRAINT "PK_EventOrderLine" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_EventOrderLine_EventOrder_EventOrderId" FOREIGN KEY ("EventOrderId") REFERENCES "EventOrder" ("Id") ON DELETE CASCADE
